  // Service-level carrier selection logic
  public static ShippingCarrier selectCarrier(Address destination, BigDecimal weight) {
    if ((!Objects.equals(destination.country(), "US"))) {
      return ShippingCarrier.FED_EX;
    }
    if ((weight.compareTo(BigDecimal.valueOf(70)) > 0)) {
      return ShippingCarrier.UPS;
    }
    return ShippingCarrier.USPS;
  }

  public static OffsetDateTime calculateEstimatedDelivery(
      ShippingCarrier carrier, Address destination) {
    var days = Functions.getEstimatedDays(carrier, destination);
    return OffsetDateTime.now().plusDays(days);
  }

  public static Integer getEstimatedDays(ShippingCarrier carrier, Address destination) {
    var isInternational = (!Objects.equals(destination.country(), "US"));
    if (isInternational) {
      // Ternary expression using '? :'
      return ((Objects.equals(carrier, ShippingCarrier.FED_EX)) ? 5 : 7);
    }
    if ((Objects.equals(carrier, ShippingCarrier.USPS))) {
      return 5;
    }
    if ((Objects.equals(carrier, ShippingCarrier.UPS))) {
      return 3;
    }
    if ((Objects.equals(carrier, ShippingCarrier.FED_EX))) {
      return 3;
    }
    return 5;
  }

